import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, usePeople } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { claimed, live, useClaims } from './claims';
import { useFigure } from '../locale/locale';
import { useColumnShown } from '../columns/columns';

// A person's claimed (the sum of their claims, leaving out corrections) and the sheet's claimed-total (everyone's).
function ClaimedHead() {
  if (!useColumnShown()('claimed')) return null;
  return <th>Claimed</th>;
}

function PersonClaimed({ person }: { person: Person }) {
  const shown = useColumnShown();
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const claims = useClaims(sheet);
  if (!shown('claimed')) return null;
  return <td data-testid="person-claimed">{fig(claimed(live((claims.data ?? []).filter((c) => c.personId === person.id), [person])))}</td>;
}

function ClaimedTotal() {
  const fig = useFigure();
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  return (
    <p>
      Claimed total <strong data-testid="rollup-claimed-total">{fig(claimed(live(claims.data ?? [], people.data)))}</strong>
    </p>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 10, Component: ClaimedHead }),
  PersonColumns.fill({ order: 10, Component: PersonClaimed }),
  HomeMain.fill({ order: 30, Component: ClaimedTotal }),
];
    enabled: sheet !== '',
  });
}

/** Amounts are added in whole cents, so the sum is exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** Whether the claim corrects another: it names the number of the claim it corrects. */
export const correctsAnother = (c: Claim) => c.corrects !== null && c.corrects.trim() !== '';

/** The sum of the amounts of those of these claims that count, leaving out claims that correct another,
 *  with two decimals. */
export function claimed(claims: Claim[]): string {
  return (claims.filter((c) => counts(c) && !correctsAnother(c)).reduce((sum, c) => sum + cents(c.amount), 0) / 100).toFixed(2);
}

/** The ids of the claims selected for a bulk action, kept in the URL (`selectedClaims`, comma separated). */
export function useSelectedClaims(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('selectedClaims', asString);
  const ids = raw.split(',').filter((s) => s !== '').map(Number).filter((n) => !Number.isNaN(n));
  return [ids, (next) => setRaw(next.join(','))];
